Input: {"question": "Where is Mahkota located?", "source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0382-c71143f5ded1:d00", "start": 0, "end": 80, "text": "Bandar Indera Mahkota Indera Mahkota is a township in Kuantan, Pahang, Malaysia."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0382-c71143f5ded1:d00", "start": 81, "end": 114, "text": "This township was opened in 1983."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0382-c71143f5ded1:d00", "start": 115, "end": 217, "text": "It is once known as Atabara (before it was developed) and now it is a well-developed residential area."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0382-c71143f5ded1:d00", "start": 218, "end": 243, "text": "Its postal code is 25200."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0382-c71143f5ded1:d00", "start": 244, "end": 294, "text": "Indera Mahkota is about northeast of Kuantan Town."}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0382-c71143f5ded1:d00", "start": 295, "end": 367, "text": "The historical tin-mining town of Sungai Lembing is from Indera Mahkota."}, "D1S7": {"document_number": 1, "doc_id": "ramdocs-0382-c71143f5ded1:d00", "start": 368, "end": 484, "text": "It is also the main road for road users from Kuantan to use the East Coast Expressway (LPT) via Kuantan Interchange."}, "D1S8": {"document_number": 1, "doc_id": "ramdocs-0382-c71143f5ded1:d00", "start": 485, "end": 613, "text": "Indera Mahkota is also more accessible to Sultan Haji Ahmad Shah Airport and Gambang/resort city through Kuantan Bypass Highway."}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0382-c71143f5ded1:d01", "start": 0, "end": 72, "text": "Bandar Indera Mahkota Indera Mahkota is a township in Sydney, Australia."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0382-c71143f5ded1:d01", "start": 73, "end": 106, "text": "This township was opened in 1983."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0382-c71143f5ded1:d01", "start": 107, "end": 209, "text": "It is once known as Atabara (before it was developed) and now it is a well-developed residential area."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0382-c71143f5ded1:d01", "start": 210, "end": 235, "text": "Its postal code is 25200."}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0382-c71143f5ded1:d01", "start": 236, "end": 285, "text": "Indera Mahkota is about northeast of Sydney City."}, "D2S6": {"document_number": 2, "doc_id": "ramdocs-0382-c71143f5ded1:d01", "start": 286, "end": 358, "text": "The historical tin-mining town of Sungai Lembing is from Indera Mahkota."}, "D2S7": {"document_number": 2, "doc_id": "ramdocs-0382-c71143f5ded1:d01", "start": 359, "end": 474, "text": "It is also the main road for road users from Sydney to use the East Coast Expressway (LPT) via Kuantan Interchange."}, "D2S8": {"document_number": 2, "doc_id": "ramdocs-0382-c71143f5ded1:d01", "start": 475, "end": 587, "text": "Indera Mahkota is also more accessible to Sydney Airport and Gambang/resort city through Kuantan Bypass Highway."}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0382-c71143f5ded1:d02", "start": 0, "end": 81, "text": "Bandar Mahkota Cheras Mahkota Cheras is a township in Cheras, Selangor, Malaysia."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0382-c71143f5ded1:d02", "start": 82, "end": 147, "text": "It was developed by Narajaya Sdn Bhd, a subsidiary of Lion Group."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0382-c71143f5ded1:d02", "start": 148, "end": 239, "text": "Construction commenced in late 1999 or early 2000 on a freehold plot of about 365 hectares."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0382-c71143f5ded1:d02", "start": 240, "end": 374, "text": "Mostly consisting of two-storey terraced houses, the population is estimated to be in excess of 50,000 in more than 10,000 households."}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0382-c71143f5ded1:d02", "start": 375, "end": 507, "text": "There are also a few smaller developments by other developers in the same township, e.g., Cheras Vista and Pinggiran Mahkota Cheras."}, "D3S6": {"document_number": 3, "doc_id": "ramdocs-0382-c71143f5ded1:d02", "start": 508, "end": 615, "text": "It is located in the mukim (sub-district) of Cheras, daerah (district) of Ulu Langat and state of Selangor."}, "D4S1": {"document_number": 4, "doc_id": "ramdocs-0382-c71143f5ded1:d03", "start": 0, "end": 160, "text": "brainchild of Tunku Ibrahim Ismail, the Crown Prince \"(Tunku Mahkota)\" of Johor due to his desire to meet with fellow Johoreans and provide charity to the poor."}, "D4S2": {"document_number": 4, "doc_id": "ramdocs-0382-c71143f5ded1:d03", "start": 161, "end": 326, "text": "According to him, during the feudal age, the king or the crown prince rode an elephant to travel all over the state for the same reason as the Kembara Mahkota Johor."}, "D4S3": {"document_number": 4, "doc_id": "ramdocs-0382-c71143f5ded1:d03", "start": 327, "end": 534, "text": "The royal tour debuted on 2 July 2001, participated by a group of 28 motorcyclists led by the Tunku Mahkota himself and covered all 8 districts (now 10 districts) in Johor, with the total distance of 870 km."}, "D4S4": {"document_number": 4, "doc_id": "ramdocs-0382-c71143f5ded1:d03", "start": 535, "end": 557, "text": "During the tour, Tunku"}, "D5S1": {"document_number": 5, "doc_id": "ramdocs-0382-c71143f5ded1:d04", "start": 0, "end": 685, "text": "Pejabat Jurutulis Dewan Negeri Johor Pejabat Menteri Besar ICT @ Johor Jabatan Landskap Majlis Sukan Pemantauan Bahagian Pemantauan Projek dan Kesejahteraan Rakyat EKSA Direktori Johor Direktori Staf Perkhidmatan Aplikasi Dalam Talian Muat Turun Penerbitan Arkib Hebahan Pekeliling Garis Panduan Surat Edaran Undang-Undang Kecil Data Terbuka Kerajaan Jadual Peperiksaan Perkhidmatan Awam Johor Hubungi Kami  Utama 5 Rakyat 5 Kembara Mahkota Johor 5 2023 2023  Pentadbir Portal 1 Pautan Penting Dasar Keselamatan Dasar Privasi Penafian Bantuan Kerajaan Malaysia Statistik Pelawat Pelawat Hari Ini : 353 Jumlah Pelawat : 1731339 Tarikh Kemaskini  Friday , 28 March 2025 Hubungi Kami "}}, "candidates": [{"candidate_id": "C0", "answer": "Kuantan, Pahang, Malaysia", "card_ids": ["ramdocs-0382-c71143f5ded1:d00:c0"]}, {"candidate_id": "C1", "answer": "Sydney, Australia", "card_ids": ["ramdocs-0382-c71143f5ded1:d01:c0"]}, {"candidate_id": "C2", "answer": "Cheras, Selangor, Malaysia", "card_ids": ["ramdocs-0382-c71143f5ded1:d02:c0"]}], "original_cards": [{"doc_id": "ramdocs-0382-c71143f5ded1:d00", "card_id": "ramdocs-0382-c71143f5ded1:d00:c0", "entity": "Mahkota", "scope": "Location", "claim": "Indera Mahkota is a township in Kuantan, Pahang, Malaysia.", "answer": "Kuantan, Pahang, Malaysia", "quote": "Bandar Indera Mahkota Indera Mahkota is a township in Kuantan, Pahang, Malaysia.", "original_document_number": 1}, {"doc_id": "ramdocs-0382-c71143f5ded1:d01", "card_id": "ramdocs-0382-c71143f5ded1:d01:c0", "entity": "Indera Mahkota", "scope": "Location", "claim": "Indera Mahkota is a township in Sydney, Australia.", "answer": "Sydney, Australia", "quote": "Bandar Indera Mahkota Indera Mahkota is a township in Sydney, Australia.", "original_document_number": 2}, {"doc_id": "ramdocs-0382-c71143f5ded1:d02", "card_id": "ramdocs-0382-c71143f5ded1:d02:c0", "entity": "Mahkota Cheras", "scope": "Location", "claim": "Mahkota Cheras is a township in Cheras, Selangor, Malaysia.", "answer": "Cheras, Selangor, Malaysia", "quote": "Bandar Mahkota Cheras Mahkota Cheras is a township in Cheras, Selangor, Malaysia. It was developed by Narajaya Sdn Bhd, a subsidiary of Lion Group. Construction commenced in late 1999 or early 2000 on a freehold plot of about 365 hectares. Mostly consisting of two-storey terraced houses, the population is estimated to be in excess of 50,000 in more than 10,000 households. There are also a few smaller developments by other developers in the same township, e.g., Cheras Vista and Pinggiran Mahkota Cheras. It is located in the mukim (sub-district) of Cheras, daerah (district) of Ulu Langat and state of Selangor.", "original_document_number": 3}], "initial_answers": ["Kuantan, Pahang, Malaysia", "Sydney, Australia", "Cheras, Selangor, Malaysia"]}

